const response = $input.first().json.response || $input.first().json.choices?.[0]?.message?.content || '';
const inputData = $node['When Executed by Another Workflow'].json;

console.log('Raw LLM Response:', response.substring(0, 200));
console.log('Input Company Name:', inputData.company_name);

// Clean the response
let cleanedContent = response
  .replace(/^.*?\*\*Section 1:/gi, '**Section 1:')
  .replace(/\[EXTRACT REAL COMPANY NAME\]/g, inputData.company_name || 'Target Company')
  .replace(/\[.*?\]/g, '') // Remove any remaining brackets
  .trim();

// Ensure proper HTML formatting
if (!cleanedContent.includes('<h3>')) {
  cleanedContent = cleanedContent
    .replace(/\*\*Section 1: Introduction & Engagement Context\*\*/g, '<h3>1. Introduction & Engagement Context</h3>')
    .replace(/\*\*Engagement Summary:\*\*/g, '<h4>1.1 Engagement Summary</h4><p>')
    .replace(/\*\*Evaluative Lens:\*\*/g, '</p><h4>1.2 Evaluative Lens</h4><p>')
    .replace(/\*\*Scope of Review:\*\*/g, '</p><h4>1.3 Scope of Review</h4><p>')
    .replace(/\*\*Data Sources & Limitations:\*\*/g, '</p><h4>1.4 Data Sources & Limitations</h4><p>')
    .replace(/\*\*Authorship:\*\*/g, '</p><h4>1.5 Authorship</h4><p>')
    .replace(/\*\*Appendix Routing:\*\*/g, '</p><h4>1.6 Appendix Routing</h4><p>') + '</p>';
}

console.log('Final Section 1 Content:', cleanedContent.substring(0, 200));

return {
  json: {
    section_content: cleanedContent,
    company_name: inputData.company_name,
    company_id: inputData.company_id,
    section_type: 'introduction_engagement_context'
  }
};
